from scapy.utils import rdpcap
from scapy.layers.http import HTTPRequest  # import HTTP packet dissector
from scapy.compat import raw


def extract_post_payloads(pcap_path):
    packets = rdpcap(pcap_path)
    post_payloads = []

    for packet in packets:
        if packet.haslayer(HTTPRequest):
            if packet[HTTPRequest].Method.decode() == "POST":
                # Raw payload extraction based on packet content
                payload = raw(packet[HTTPRequest].payload)
                post_payloads.append(payload)

    return post_payloads


def save_results(payloads, save_path):
    with open(save_path, "wb") as f:
        for payload in payloads:
            f.write(payload + b"\n")


