import re
import base64

input_file = '/home/ctfplayer/results/output_payloads.txt'
outfile_path = '/home/ctfplayer/results/decoded_payloads.txt'

# Pattern to locate hexadecimal-encoded data
hexadecimal_pattern = r'n=([0-9a-f]+)'

# Function to decode hexadecimal strings
def decode_hex(payload):
    try:
        return bytes.fromhex(payload).decode('utf-8')
    except ValueError:
        return None

# Function to process and decode payloads
def process_payloads():
    with open(input_file, 'r') as infile:
        content = infile.read()

    decoded_results = []

    matches = re.findall(hexadecimal_pattern, content)

    for match in matches:
        decoded = decode_hex(match)
        if decoded is not None:
            decoded_results.append(decoded)

    with open(outfile_path, 'w') as outfile:
        outfile.write('\n'.join(decoded_results))

if __name__ == "__main__":
    process_payloads()
